import urllib.request
import urllib.error
import time


class RateLimitError(Exception):
    pass


class ServerError(Exception):
    pass


class ClientError(Exception):
    pass


class ConnectionError(Exception):
    pass


class APIClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url.rstrip('/')
        self.timeout = timeout

    def get(self, path):
        url = f"{self.base_url}{path}"
        last_exception = None

        while True:
            try:
                req = urllib.request.Request(url)
                with urllib.request.urlopen(req, timeout=self.timeout) as response:
                    status = response.getcode()
                    body = response.read().decode('utf-8')

                    if status == 429:
                        last_exception = RateLimitError(f"Rate limit hit for {url}")
                        if last_exception is None:
                            raise last_exception
                        time.sleep(0.5 * (2 ** (last_exception._retry_count if hasattr(last_exception, '_retry_count') else 0)))
                        last_exception._retry_count = getattr(last_exception, '_retry_count', 0) + 1
                        if last_exception._retry_count > 3:
                            raise last_exception
                        continue
                    elif 500 <= status < 600:
                        last_exception = ServerError(f"Server error {status} for {url}")
                        if last_exception is None:
                            raise last_exception
                        time.sleep(1)
                        last_exception._retry_count = getattr(last_exception, '_retry_count', 0) + 1
                        if last_exception._retry_count > 1:
                            raise last_exception
                        continue
                    elif 400 <= status < 500 and status != 429:
                        raise ClientError(f"Client error {status} for {url}")
                    else:
                        return body

            except urllib.error.HTTPError as e:
                status = e.code
                if status == 429:
                    last_exception = RateLimitError(f"Rate limit hit for {url}")
                    if last_exception is None:
                        raise last_exception
                    time.sleep(0.5 * (2 ** (last_exception._retry_count if hasattr(last_exception, '_retry_count') else 0)))
                    last_exception._retry_count = getattr(last_exception, '_retry_count', 0) + 1
                    if last_exception._retry_count > 3:
                        raise last_exception
                    continue
                elif 500 <= status < 600:
                    last_exception = ServerError(f"Server error {status} for {url}")
                    if last_exception is None:
                        raise last_exception
                    time.sleep(1)
                    last_exception._retry_count = getattr(last_exception, '_retry_count', 0) + 1
                    if last_exception._retry_count > 1:
                        raise last_exception
                    continue
                elif 400 <= status < 500 and status != 429:
                    raise ClientError(f"Client error {status} for {url}")
                else:
                    raise

            except urllib.error.URLError as e:
                last_exception = ConnectionError(f"Connection error for {url}: {e.reason}")
                if last_exception is None:
                    raise last_exception
                time.sleep(1)
                last_exception._retry_count = getattr(last_exception, '_retry_count', 0) + 1
                if last_exception._retry_count > 1:
                    raise last_exception
                continue

            except Exception as e:
                raise

        raise last_exception
